import random
import time


def retry(fn, attempts=5, base=0.5, cap=30.0, exceptions=(Exception,), sleep=time.sleep):
    """Call fn(); on failure wait base * 2**n (capped, with full jitter) and retry."""
    for n in range(attempts):
        try:
            return fn()
        except exceptions:
            if n == attempts - 1:
                raise
            sleep(random.uniform(0, min(cap, base * 2 ** n)))
```

Usage: `retry(lambda: fetch(url), exceptions=(OSError,))`. Narrow `exceptions` to the transient errors, because the default retries everything, including bugs.

